import {escapeHTML as e,safeURL,MONEY,comparison,greenFeeText,extraFeeText,estimateCost} from './core.js';
import {naverRating,feeValue,road,drivingLink,naverSearch,photoFor,canonicalSource,courseCategory,VERIFIED_TYPES} from './data.js';
const dash='—';
export const compactMoney=value=>Number.isFinite(value)?MONEY(value):dash;
export function feeDisplay(c,day){const values=[...new Set((c.official?.green_fees||[]).filter(f=>f.holes===18&&f.per==='person'&&Number.isFinite(f[day])).map(f=>f[day]))].sort((a,b)=>a-b);if(!values.length)return dash;return values.length>1?`${values[0].toLocaleString('ko-KR')}~${values.at(-1).toLocaleString('ko-KR')}원 · 일반`:`${MONEY(values[0])} · 일반`;}
export function routeText(c,origin){const r=road(c,origin);return r?`약 ${r.distanceKm.toFixed(0)} km · ${Math.floor(r.durationMin/60)}시간 ${Math.round(r.durationMin%60)}분${r.warning?' *':''}`:dash;}
export function ratingText(c){const r=naverRating(c);return r?`★ ${r.value.toFixed(2)} (${r.count.toLocaleString('ko-KR')})`:'— · 네이버 미연결';}
function brief(c,key){const values=(c.reviewSummary?.verified===true?c.reviewSummary[key]:[])||[];return values.slice(0,2).map(v=>String(v).slice(0,24)).join(' · ')+(values.length&&c.reviewSummary.provider?' ['+c.reviewSummary.provider+']':'')||dash;}
function link(url,label){const u=safeURL(url);return u?`<a href="${e(u)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a>`:'';}
export function bookingLinks(c){const o=c.official;const website=o?.website?.value||c.website||c.tags?.website||c.tags?.['contact:website'];const out=[link(website,o?'공식 홈페이지':'등록 웹사이트 · 미검증')];if(o?.booking?.status==='verified')out.push(link(o.booking.url,'공식 예약'));for(const b of c.bookingLinks||[]){if(b.verified===true)out.push(link(b.url,`${b.provider} · ${b.kind==='course'?'코스 페이지':b.kind==='search'?'검색':'서비스'}`));}return out.filter(Boolean).join(' ');}
export function compactRows(c){return [['네이버 별점 / 후기',ratingText(c)],['주중 18홀 / 1인',feeDisplay(c,'weekday')],['주말 18홀 / 1인',feeDisplay(c,'weekend')],['캐디피',c.official?.caddie_fee?.value!=null?`${MONEY(c.official.caddie_fee.value)} · ${c.official.caddie_fee.per==='team'?'팀당':c.official.caddie_fee.per==='person'?'1인당':'단위미확인'}`:dash],['위치',c.official?.address?.value||c.address||c.region||(Number.isFinite(c.lat)?`${c.lat.toFixed(3)}, ${c.lon.toFixed(3)} · 지도`:dash)],['서울시청 · 도로',routeText(c,'seoul')],['부산시청 · 도로',routeText(c,'busan')],['후기 장점',brief(c,'pros')],['후기 유의',brief(c,'cons')]];}
export function photoCredit(photo){return `${link(photo.sourceUrl,'사진 출처')} · ${e(photo.author||'')} · ${link(photo.licenseUrl,photo.license)||e(photo.license)} · 썸네일 크기 조정`;}
export function reviewEvidenceRows(c){const r=c.reviewSummary;if(!r)return [];const kinds={provider_ai_summary_and_public_reviews:'제공처 AI 요약·일부 공개후기',single_public_user_review:'공개 이용자 후기 1건',author_visit_report_2026_08_25:'작성자 방문기 · 고유 포스트 URL 미확보'};return [['후기 제공처',r.provider||'미확인'],['후기 자료 종류',`${kinds[r.kind]||r.kind||'종류 미확인'} (${r.kind||'미제공'})`],['후기 표본수',Number.isFinite(r.sample_count)?`${r.sample_count}건`:'표본수 미확인'],['후기 대표성',r.representative===true?'대표성 검증됨':'일부 표본 · 전체 이용자 총평 아님'],['후기 적용 한계',r.conditions||'한계 미확인'],['후기 확인시각',r.verified_at||'미제공'],...(r.contentOmitted?[['후기 반출','후기 본문·요약 내용은 외부 반출에서 제외']]:[])];}
export function routeEvidenceRows(c){const rows=[];for(const origin of ['seoul','busan']){const r=c.routes?.[origin];if(!r)continue;const label=origin==='seoul'?'서울시청':'부산시청';const point=r.destination||{lat:c.lat,lon:c.lon};rows.push([`${label} 경로 실제 조회시각`,r.checkedAt||'미제공'],[`${label} 경로 제공처`,r.provider||'미제공'],[`${label} 목적지 대표점`,`${point.lat}, ${point.lon} · 대표점 기준 · 실제 입구 미검증`],[`${label} 도로 스냅 거리`,Number.isFinite(r.snapDistanceMeters)?`${r.snapDistanceMeters.toFixed(1)} m`:'미제공'],[`${label} 도로 스냅 경고`,r.warning||(Number.isFinite(r.snapDistanceMeters)?'추가 경고 없음 · 실제 진입 보증 아님':'스냅 상태 미제공')],[`${label} 교통 반영`,'실시간 교통 미반영 · 캐시값은 실제 조회시각 유지']);}return rows;}
export function evidence(c){const photo=photoFor(c);const rows=comparison(c).map(([k,v])=>k==='풍경·전경 사진'&&photo?[k,`${c.name} 사용사진 · ${photo.author||''} · ${photo.license}`]:[k,v]).concat(c.originalCoordinate?[['원 OSM 대표점',`${c.originalCoordinate.lat}, ${c.originalCoordinate.lon}`],['표시 위치','공식 지도점 · 실제 입구 미검증'],['공식 위치 출처',c.positionAudit.source_url]]:[]).concat(c.sourceName&&c.sourceName!==c.name?[['OSM 원명칭',c.sourceName],['명칭 대조',c.identityMatch?.basis||'원천 ID 일치']]:[]).concat(reviewEvidenceRows(c)).concat(routeEvidenceRows(c)).concat(VERIFIED_TYPES[c.id]?[['시설 유형 검증',VERIFIED_TYPES[c.id].basis],['시설 유형 출처',VERIFIED_TYPES[c.id].sourceUrl]]:[['시설 유형 해석','명시된 스크린/연습/파크 명칭만 분류 · 나머지 미검증']]).concat(photo?[['사진 확인시각',photo.checkedAt||'미제공'],['사진 사용근거',photo.sourceUrl]]:[]);return `<details class="evidence"><summary>조건·출처 보기</summary><p>일반요금 참고값 · 선택일 확정견적 아님. 복수 요금은 범위로 표시합니다. 도로자료 — 는 미조회/미제공입니다. OSRM 도로 추정은 실시간 교통 미반영이며 표시 후보에만 조회합니다. 대표점 도로 스냅이 1km를 넘으면 *로 표시합니다.</p><dl class="comparison">${rows.map(([k,v])=>`<dt>${e(k)}</dt><dd>${e(v)}</dd>`).join('')}</dl><p>${link(canonicalSource(c),'원자료')} ${c.reviewSummary?.source_url?link(c.reviewSummary.source_url,'후기 표본 출처 · 네이버 아님'):''} ${road(c,'seoul')?link('https://routing.openstreetmap.de/about.html','경로 © OSRM / OpenStreetMap'):''}${c.official?.fee_guide?.value?' '+link(c.official.fee_guide.value,'공식 요금표'):''}${c.official?.coordinates?.source_url?' '+link(c.official.coordinates.source_url,'위치 출처'):''}</p>${photo?`<p>${photoCredit(photo)}</p>`:''}</details>`;}
function safeExportCourse(c){return c.reviewSummary?.exportAllowed===false?{...c,reviewSummary:{...c.reviewSummary,pros:[],cons:[],contentOmitted:true}}:c;}
export function card(c,i,{favorites=new Set(),compared=new Set(),selectedId=null}={}){const photo=photoFor(c);return `<article class="course-card compact-card ${selectedId===c.id?'is-selected':''}" data-course="${e(c.id)}"><div class="compact-top"><button class="course-thumb" data-map="${e(c.id)}" aria-label="${e(c.name)} 지도에서 보기">${photo?`<img src="${e(safeURL(photo.url))}" alt="${e(c.name)} 실제 코스 전경" loading="lazy" referrerpolicy="no-referrer"><span class="image-fallback" hidden>⚑</span>`:'<span class="image-fallback">⚑</span>'}</button><div class="compact-heading"><span class="course-index">${String(i+1).padStart(2,'0')} / ${e(c.tags?.['golf:holes']||'—')} HOLES · ${e(courseCategory(c))}</span><h3><button class="text-button course-name" data-map="${e(c.id)}">${e(c.name)}</button></h3><a class="rating-link" href="${e(naverSearch(c))}" target="_blank" rel="noopener noreferrer">${e(ratingText(c))} ↗</a></div><button class="heart ${favorites.has(c.id)?'active':''}" data-favorite="${e(c.id)}" aria-label="${e(c.name)} 관심 저장">${favorites.has(c.id)?'♥':'♡'}</button></div><dl class="compact-values">${compactRows(c).slice(1).map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl><div class="compact-actions"><button class="secondary ${compared.has(c.id)?'active':''}" data-compare="${e(c.id)}">${compared.has(c.id)?'비교 빼기':'＋ 비교'}</button>${bookingLinks(c)}<a href="${e(drivingLink(c,'seoul')||'#')}" target="_blank" rel="noopener noreferrer">서울 출발 길찾기 ↗</a><a href="${e(drivingLink(c,'busan')||'#')}" target="_blank" rel="noopener noreferrer">부산 출발 길찾기 ↗</a></div>${evidence(c)}${photo?`<small>${photoCredit(photo)}</small>`:''}</article>`;}
export function compareTable(courses,date,party){if(!courses.length)return '<p class="catalog-note">코스에서 ＋ 비교를 눌러 최대 4곳을 담으세요.</p>';const labels=compactRows(courses[0]).map(([label])=>label);return `<div class="compare-scroll"><table><thead><tr><th>비교 항목</th>${courses.map(c=>`<th>${e(c.name)} <button class="text-button" data-compare="${e(c.id)}">×</button></th>`).join('')}</tr></thead><tbody>${labels.map((label,i)=>`<tr><th>${e(label)}</th>${courses.map(c=>`<td>${e(compactRows(c)[i][1])}</td>`).join('')}</tr>`).join('')}<tr><th>선택일 1인 총액</th>${courses.map(c=>`<td>${e(estimateCost(c,date,party).text)}</td>`).join('')}</tr></tbody></table></div>`;}
export function listingTable(courses){return `<div class="compare-scroll"><table class="listing-table"><thead><tr><th>코스 / 위치</th><th>네이버</th><th>주중 / 주말 18홀·1인</th><th>캐디피</th><th>서울 / 부산 도로 추정</th></tr></thead><tbody>${courses.map(c=>`<tr><th>${e(c.name)}<br><small>${e(compactRows(c)[4][1])}</small></th><td>${e(ratingText(c))}</td><td>${e(feeDisplay(c,'weekday'))}<br>${e(feeDisplay(c,'weekend'))}</td><td>${e(compactRows(c)[3][1])}</td><td>${e(routeText(c,'seoul'))}<br>${e(routeText(c,'busan'))}</td></tr>`).join('')}</tbody></table></div>`;}
export function exportReport(snapshot,items,options={}){items=items.map(safeExportCourse);const courses=(options.compareCourses||[]).slice(0,4).map(safeExportCourse),detailMap=new Map([...courses,...items].map(c=>[c.id,c])),detailCourses=[...detailMap.values()],date=options.date||'',party=options.partySize||4;return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FRI ATLAS / 비교 자료</title><style>body{font:13px/1.7 system-ui,sans-serif;max-width:1100px;margin:auto;padding:30px;background:#f4f7ef;color:#193f35}h1{font:44px Georgia,serif}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #cbded4;padding:9px;vertical-align:top;text-align:left}th{background:#e5eee1}a{color:#17654a}.comparison{display:grid;grid-template-columns:1fr 2fr}.comparison dt,.comparison dd{padding:7px;margin:0;border-bottom:1px solid #cbded4}section{margin:25px 0;break-inside:avoid}button{display:none}@media print{body{padding:0;background:white}details{display:block}}</style></head><body><b>FRI ATLAS / FIELD NOTES</b><h1>Your next fairway.</h1><p>분석 ${e(snapshot.time)} · 데이터 ${e(snapshot.dataTime||'미제공')} · ${e(options.sortLabel||'추천순')} · 최대 ${options.limit===20?20:10}<br>영역 남 ${snapshot.bounds.s.toFixed(5)} / 서 ${snapshot.bounds.w.toFixed(5)} / 북 ${snapshot.bounds.n.toFixed(5)} / 동 ${snapshot.bounds.e.toFixed(5)}<br>분석 후보 ${snapshot.items.length}곳 · 표시 ${items.length}곳 · 위치 표본이며 전국 전체 운영 명부가 아닙니다.<br>선택 날짜 ${e(date||'미선택')} · 팀 인원 ${e(party)}명. 네이버 미연결/도로자료/사진 결측은 — 입니다. 도로값은 OSRM·OSM 도로 추정이며 실시간 교통을 반영하지 않습니다. 내보내기 권한 없는 후기내용은 제외하고 출처·종류·표본 한계는 보존합니다.</p><section><h2>간결 비교</h2>${listingTable(items)}</section><section><h2>별도 선택 비교 ${courses.length}/4곳</h2>${compareTable(courses,date,party)}</section>${detailCourses.map(c=>`<section><h2>${e(c.name)}</h2>${photoFor(c)?`<figure><img src="${e(safeURL(photoFor(c).url))}" alt="${e(c.name)} 코스 전경" style="max-width:100%;max-height:220px"><figcaption>${photoCredit(photoFor(c))}</figcaption></figure>`:''}<p>${bookingLinks(c)} ${link(naverSearch(c),'네이버 검색 · 평가 자동수집 아님')}</p>${evidence(c)}</section>`).join('')}<footer><p>일반 그린피는 복수 조건의 최저~최고 안내 범위이며 단일 조건이면 해당 일반요금을 표시합니다. 가격 정렬 키는 최저값이고 선택일 확정견적이 아닙니다. 총액은 모든 필수조건이 검증된 경우만 산출합니다. 별점 미연결은 공식요금 확인·명시 특수시설 후순위·이름순으로 표시하며 품질순위가 아닙니다.</p><a href="https://www.openstreetmap.org/copyright">© OpenStreetMap contributors / ODbL</a></footer></body></html>`;}
